use serde::{Deserialize, Serialize};

use crate::policy::resource_policy::PowerMode;

/// User personal configuration.
///
/// Privacy engagement (reference DATA_PRIVACY.md):
/// - history_enabled Default false: Long history default not recorded.
/// - profile_enabled default false: personal models are not generated by default.
/// - cloud_inference_allowed Default false: Cloud inference is disabled by default.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct UserProfile {
    pub version: String,
    pub history_enabled: bool,
    pub profile_enabled: bool,
    pub retention_days: u32,
    pub preferred_power_mode: Option<PowerMode>,
    pub cloud_inference_allowed: bool,
    pub updated_at_unix_secs: u64,
}

impl Default for UserProfile {
    fn default() -> Self {
        Self {
            version: "1".to_string(),
            history_enabled: false,
            profile_enabled: false,
            retention_days: 7,
            preferred_power_mode: None,
            cloud_inference_allowed: false,
            updated_at_unix_secs: 0,
        }
    }
}

impl UserProfile {
    /// Whether history can be recorded.
    pub fn can_record(&self) -> bool {
        self.history_enabled
    }

    /// Whether personal models can be used.
    pub fn can_personalize(&self) -> bool {
        self.profile_enabled
    }

    /// Whether cloud inference is permitted.
    pub fn can_use_cloud(&self) -> bool {
        self.cloud_inference_allowed
    }
}
